def active (s : BlockState) (p_cumsum_seq_len : RegionName)
    (i : Fin BLOCK_P) : Prop :=
  tokenOffset s p_cumsum_seq_len i < batchEnd s p_cumsum_seq_len

def active (s : BlockState) (idx : TileIndex [BM, BD]) : Prop :=
  s.pids 0 * BM + idx.1.val < BN * NC ∧ idx.2.1.val < HA

/-- The mathematical result and every cell outside the actual write mask. -/

def natSlidingWindowKeepG (SM BM BN off size : Nat) {NC : Nat}
    (i : Fin BM) (j : Fin NC) : Prop :=
  natDist3G SM BM BN off i j < size

def natComplementSlidingWindowKeepG (SM BM BN off size : Nat) {NC : Nat}
    (i : Fin BM) (j : Fin NC) : Prop :=
  size ≤ natDist3G SM BM BN off i j

def retained (startM blockM row key : Nat) (offset size : Int) : Prop :=
  0 ≤ distance startM blockM row key offset ∧
    distance startM blockM row key offset < size

/-- Every valid key retained by any row lies inside the source's clipped
sliding-window interval. This holds for arbitrary signed offsets and sizes;
no positivity assumption on the window size is introduced. -/

def alActive {BD : Nat} (s : BlockState) (H BM : Nat)
    (idx : TileIndex [BM, BD]) : Prop :=
  alRow s BM idx.1 < H

def windowAllows (p : Parameters) (row key : Nat) : Prop :=
  p.window = Bool.false ∨ if p.complement then p.size ≤ (row : Int) - key + p.offset
    else 0 ≤ (row : Int) - key + p.offset ∧ (row : Int) - key + p.offset < p.size

def attentionScoreCase1IOMask (p₀ BN swo sws : Nat) (c i j : Nat) : Prop :=
  0 ≤ attentionScoreCase1IODist p₀ BN swo c i j
    ∧ attentionScoreCase1IODist p₀ BN swo c i j < sws

def windowAllows (window complement : Bool) (offset size : Int) (row key : Nat) : Prop :=
  window = Bool.false ∨ if complement then size ≤ distance row key offset
    else 0 ≤ distance row key offset ∧ distance row key offset < size

def InjectiveOutput (c : Config) (BM BD : Nat) : Prop :=
  ∀ a b, RealEpilogue.active c BM BD a = Bool.true → RealEpilogue.active c BM BD b = Bool.true →
    RealEpilogue.address c BM BD a = RealEpilogue.address c BM BD b → a = b

def Models {α : Type} [Inhabited α] (R : Rules) (M : Algebra α) (D : Domain α) : Prop :=
  ∀ lhs rhs, Spec.Derivation R.assumptions [lhs] [rhs] → ∀ s,
    DomainHolds D lhs s → DomainHolds D rhs s → observe M lhs s = observe M rhs s

def RankActive (p : Parameters) (split : Nat) (k : Fin p.K) : Prop :=
  ∃ c : Fin (RealLoop.numKIters p.K (p.BK * p.splits)), ∃ e : Fin p.BK,
    rank p split c.val e.val = k.val

def validCSR (p : RealProgram.Parameters) (pid₀ pid₁ : Nat) (xs : RealIO.Inputs) : Prop :=
  let sched := schedule p pid₀ pid₁
  let slot := fun visit : Nat => ((sched.layout * p.columnStride : Nat) : Int) + CSRMath.first sched xs + (visit : Int)
  (∀ visit, visit < CSRMath.count sched xs → 0 ≤ slot visit) ∧
  (∀ visit, visit < CSRMath.count sched xs → 0 ≤ xs.columnIndex (slot visit))

def Bounds (bounds : RegionBounds) (s : BlockState) (BM BD : Nat)
    (p : RealProgram.Parameters) (second : Bool) : Prop :=
  ∀ r d, RealSetup.rows s BM r < p.context → offset s BM BD p second r d < bounds p.Out

def active (s : BlockState) (BM BN : Nat) (p : RealProgram.Parameters)
    (i : TileIndex [BM, BN]) : Prop :=
  RealSetup.rows s BM BN p i.1 < RealSetup.limit s p ∧ RealSetup.columns s BN p i.2.1 < p.K

def active (BM BN length K : Nat) (rows : Fin BM → Nat)
    (columns : Fin BN → Nat) (i : TileIndex [BM, BN]) : Prop :=
  rows i.1 < length ∧ columns i.2.1 < K

def active (BM BN chunk : Nat) (rows : Fin BM → Nat)
    (columns : Fin BN → Nat) (i : TileIndex [BM, BN]) : Prop :=
  rows i.1 < chunk ∧ columns i.2.1 < chunk

def bmmOActive (s : BlockState) (M N TILE_M TILE_N GROUP_M : Nat)
    (idx : TileIndex [TILE_M, TILE_N]) : Prop :=
  bmmRowG s TILE_M GROUP_M idx.1.val < M ∧ bmmColG s TILE_N GROUP_M idx.2.1.val < N

def active {BM BN : Nat} (p : RealProgram.Parameters) (rows : Fin BM → Nat)
    (cols : Fin BN → Nat) (i : TileIndex [BM,BN]) : Prop :=
  RealMath.active p.divM (rows i.1) p.M ∧ RealMath.active p.divN (cols i.2.1) p.N

def active (s : BlockState) (HIDDEN_DIM NUM_SEQS BLOCK_H : Nat)
    (i : Fin BLOCK_H) : Prop :=
  seqIndex s < NUM_SEQS ∧ hidIndex s BLOCK_H i < HIDDEN_DIM

def decodeActive (s : BlockState) (NUM_SEQS BLOCK_SIZE : Nat)
    (idx : TileIndex [BLOCK_SIZE, HIDDEN_DIM]) : Prop :=
  rowIndex s BLOCK_SIZE idx.1 < NUM_SEQS

def HistoryWindowSafe (p : Layout) (l : Launch) (r : RegionName)
    (count allocation : Nat) : Prop :=
  ∀ v : Fin p.BV, ∀ e : Fin p.BK,
    let bp := (RealStep.hPointer p l r count).data (v, e, PUnit.unit)
    bp.inBounds [v.val, e.val] [0, 1] = Bool.true →
      bp.address [v.val, e.val] < allocation

def singleBlockActive (s : BlockState) (T S BS : Nat)
    (idx : TileIndex [BT, BS]) : Prop :=
  idx.1.val < T ∧ sIndex s BS idx.2.1 < S

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ (t u : Nat) (i j : Fin p.BS), RealStep.active p l t i.val → RealStep.active p l u j.val →
    address p l t i.val = address p l u j.val → t = u ∧ i = j

def vNewActive (s : BlockState) (i_t i_c T V BT BC BV : Nat)
    (idx : TileIndex [BC, BV]) : Prop :=
  i_t * BT + i_c * BC + cIndex BC idx.1 < T ∧ vIndex s BV idx.2.1 < V

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ (t u : Nat) (i j : Fin p.BV), activeValue p l t i.val → activeValue p l u j.val →
    valueAddress p l t i.val = valueAddress p l u j.val → t = u ∧ i = j

def NoCollision (p : Layout) (l : Launch) (base rowStride : Nat) : Prop :=
  ∀ (e f : Fin p.BK) (i j : Fin p.BV), active p l e.val i.val → active p l f.val j.val →
    address p l base rowStride e.val i.val = address p l base rowStride f.val j.val → e = f ∧ i = j

def Represents (p : Layout) (l : Launch) (tile : StateValue p) (state : Nat → Nat → ℝ) : Prop :=
  ∀ (e : Fin p.BK) (j : Fin p.BV), e.val < p.K → valueIndex p l j.val < p.V →
    tile e j = state e.val (valueIndex p l j.val)

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ (c d : Nat) (e k : Fin p.BK) (j v : Fin p.BV),
    address p l c e.val j.val = address p l d k.val v.val → c = d ∧ e = k ∧ j = v

def cumSurfaceActive (s : BlockState) (T S BT BS : Nat)
    (idx : TileIndex [BT, BS]) : Prop :=
  cumSurfaceTIndex s BT idx.1 < T ∧ cumSurfaceSIndex s BS idx.2.1 < S

def stateActive (s : BlockState) (KSize VSize BK BV : Nat)
    (idx : TileIndex [BK, BV]) : Prop :=
  kIndexState s BK idx.1 < KSize ∧ vIndexState s BV idx.2.1 < VSize

def finalActive (s : BlockState) (KSize VSize BK BV : Nat)
    (idx : TileIndex [BK, BV]) : Prop :=
  kIndexFinal s BK idx.1 < KSize ∧ vIndexFinal s BV idx.2.1 < VSize

def NoCollision (p : Layout) (l : Launch) (base rowStride colStride : Nat) : Prop :=
  ∀ (e f : Fin p.BK) (i j : Fin p.BV), active p l e.val i.val → active p l f.val j.val →
    address p l base rowStride colStride e.val i.val = address p l base rowStride colStride f.val j.val → e = f ∧ i = j

def MatrixBounds (p : Layout) (l : Launch) (r : RegionName) (bounds : RegionBounds) : Prop :=
  ∀ (i : Fin p.BC) (e : Fin p.BK), rowActive p l i.val → e.val < p.K →
    matrixAddress p l i.val e.val < bounds r

def MatrixBounds (p : Layout) (l : Launch) (r : RegionName) (bounds : RegionBounds) : Prop :=
  ∀ (i : Fin p.BC) (e : Fin p.BK), rowActive p l i.val → featureIndex p l e.val < p.K →
    matrixAddress p l i.val e.val < bounds r

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ i j : TileIndex [p.BT,p.BV], active p l i.1.val i.2.1.val → active p l j.1.val j.2.1.val →
    outputAddress p l i.1.val i.2.1.val = outputAddress p l j.1.val j.2.1.val → i = j

def Window.NoCollision (w : Window m n) : Prop :=
  ∀ (i e : Fin m) (j f : Fin n), w.active i.val j.val → w.active e.val f.val →
    w.address i.val j.val = w.address e.val f.val → i = e ∧ j = f

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ i j : TileIndex [p.BT,p.BV], active p l i.1.val i.2.1.val → active p l j.1.val j.2.1.val →
    outputAddress p l i.1.val i.2.1.val = outputAddress p l j.1.val j.2.1.val → i = j

def NoCollision (p : Layout) (l : Launch) (base rowStride colStride : Nat) : Prop :=
  ∀ (e f : Fin p.BK) (i j : Fin p.BV), active p l e.val i.val → active p l f.val j.val →
    address p l base rowStride colStride e.val i.val = address p l base rowStride colStride f.val j.val → e = f ∧ i = j

def Window.NoCollision (w : Window m n) : Prop :=
  ∀ (i e : Fin m) (j f : Fin n), w.active i.val j.val → w.active e.val f.val →
    w.address i.val j.val = w.address e.val f.val → i = e ∧ j = f

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ i j : TileIndex [p.BT,p.BT], active p l i.1.val i.2.1.val → active p l j.1.val j.2.1.val →
    outputAddress p l i.1.val i.2.1.val = outputAddress p l j.1.val j.2.1.val → i = j

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ i j : TileIndex [p.BT,p.BV], active p l i.1.val i.2.1.val → active p l j.1.val j.2.1.val →
    outputAddress p l i.1.val i.2.1.val = outputAddress p l j.1.val j.2.1.val → i = j

def NoCollision (p : Layout) (l : Launch) (base rowStride colStride : Nat) : Prop :=
  ∀ (e f : Fin p.BK) (i j : Fin p.BV), active p l e.val i.val → active p l f.val j.val →
    address p l base rowStride colStride e.val i.val = address p l base rowStride colStride f.val j.val → e = f ∧ i = j

def NoCollision (p : Layout) (l : Launch) (address : Address p) : Prop :=
  ∀ (i k : Fin p.BH) (j m : Fin p.BC), activeOutput p l i.val j.val → activeOutput p l k.val m.val →
    address i j = address k m → i = k ∧ j = m

def outputInjective (outputRow outputCol BN BK : Nat) : Prop :=
  ∀ pk pn : Nat, Function.Injective fun j : Fin (BK*BN) =>
    (pk*BK+j.val/BN)*outputRow+(pn*BN+j.val%BN)*outputCol

def dequantizeActive (p₀ p₁ K N BLOCK_SIZE_N BLOCK_SIZE_K : Nat)
    (idx : TileIndex [BLOCK_SIZE_K, BLOCK_SIZE_N]) : Prop :=
  p₀ * BLOCK_SIZE_K + idx.1.val < K ∧ p₁ * BLOCK_SIZE_N + idx.2.1.val < N

def Outside (p : Layout) (u : BlockState) (length k : Nat) (r : RegionName) (o : Nat) : Prop :=
  r≠p.gx ∨ ∀ t, length-k≤t → t<length → ∀ j, mask p u j=Bool.true →
    offset p u t j*2≠o ∧ offset p u t j*2+1≠o

def Outside (p : Layout) (u : BlockState) (k : Nat) (r : RegionName) (o : Nat) : Prop :=
  r ≠ p.y ∨ ∀ t, t<k → ∀ j, mask p u j = Bool.true →
    offset p u t j*2 ≠ o ∧ offset p u t j*2+1 ≠ o

def active (st : BlockState) (batch_size dim BLOCK_SIZE : Nat)
    (i : Fin BLOCK_SIZE) : Prop :=
  colOffset st BLOCK_SIZE i < batch_size * dim

def forwardOutside (A : FlatAlloc) (u : BlockState) (Y Z : RegionName)
    (r : RegionName) (o : Nat) : Prop :=
  r≠A.flat ∨ (o≠A.addr Y (u.pids 0) ∧ o≠A.addr Z (u.pids 0))

def chunkedOutside (A : FlatAlloc) (u : BlockState) (Y Z : RegionName) (C : Nat)
    (r : RegionName) (o : Nat) : Prop :=
  r≠A.flat ∨ (o≠A.addr Y (u.pids 0) ∧ o≠A.addr Z (u.pids 0*C))

def backwardOutside (A : FlatAlloc) (u : BlockState) (X : RegionName) (V R B : Nat)
    (r : RegionName) (o : Nat) : Prop :=
  r≠A.flat ∨ ∀ j : Fin B, col u B j<V → o≠A.addr X (address u R B j)

def Outside (A : FlatAlloc) (u : BlockState) (X : RegionName) (V R B : Nat)
    (r : RegionName) (o : Nat) : Prop :=
  r≠A.flat ∨ ∀ j : Fin B, col u B j<V → o≠A.addr X (address u R B j)

def Outside (A : FlatAlloc) (u : BlockState) (Y Z : RegionName) (C : Nat)
    (r : RegionName) (o : Nat) : Prop :=
  r≠A.flat ∨ (o≠A.addr Y (u.pids 0) ∧ o≠A.addr Z (u.pids 0*C))

def Outside (A : FlatAlloc) (u : BlockState) (Y Z : RegionName)
    (r : RegionName) (o : Nat) : Prop :=
  r≠A.flat ∨ (o≠A.addr Y (u.pids 0) ∧ o≠A.addr Z (u.pids 0))

def backwardOutside (A : FlatAlloc) (u : BlockState) (dY : RegionName) (YR N B : Nat)
    (q : RegionName) (o : Nat) : Prop :=
  q≠A.flat ∨ ∀ j : Fin B,j.val<N → o≠A.addr dY (u.pids 0*YR+j.val)

def Outside (A : FlatAlloc) (u : BlockState) (dY : RegionName) (YR N B : Nat)
    (q : RegionName) (o : Nat) : Prop :=
  q≠A.flat ∨ ∀ j : Fin B,j.val<N → o≠A.addr dY (u.pids 0*YR+j.val)

def backwardOutside (A : FlatAlloc) (u : BlockState) (Y : RegionName) (YR N B : Nat)
    (q : RegionName) (o : Nat) : Prop :=
  q≠A.flat ∨ ∀ j : Fin B,j.val<N → o≠A.addr Y (u.pids 0*YR+j.val)

def Outside (A : FlatAlloc) (u : BlockState) (Y : RegionName) (YR N B : Nat)
    (q : RegionName) (o : Nat) : Prop :=
  q≠A.flat ∨ ∀ j : Fin B,j.val<N → o≠A.addr Y (u.pids 0*YR+j.val)

def Written (row QR H B firstHead cur o : Nat) : Prop :=
  ∃ t,firstHead≤t ∧ t<cur ∧ ∃ j : Fin B,j.val<H/2 ∧
    (o=Reference.first row QR H t j.val ∨ o=Reference.second row QR H t j.val)

def Written (row group QR H heads B o : Nat) : Prop :=
  ∃ k,start group≤k ∧ k<stop group heads ∧ ∃ j : Fin B,j.val<H/2 ∧
    (o=first row QR H k j.val ∨ o=second row QR H k j.val)

def Outside (A : FlatAlloc) (p : Layout) (l : Launch) (r : BackwardRegions)
    (region : RegionName) (off : Nat) : Prop :=
  region ≠ A.flat ∨ ∀ q z, Written p l r q z → off ≠ A.addr q z

def Outside (A : FlatAlloc) (p : Layout) (l : Launch) (r : ForwardRegions)
    (storeFinal : Bool) (region : RegionName) (off : Nat) : Prop :=
  region ≠ A.flat ∨ ∀ q z, Written p l r storeFinal q z → off ≠ A.addr q z

def activeKV (s : BlockState) (DK DV BK BV : Nat)
    (idx : TileIndex [BV, BK]) : Prop :=
  activeK s DK BK idx.2.1 ∧ activeV s DV BV idx.1

def SourceCovers (p : Parameters) (pid numCtas x : Nat) : Prop :=
  if p.oneTile then TileCovers p (pid * p.block) x
  else IterCovers p pid numCtas p.iterations 0 x

def OpSame (p : Option ComputeDType) {d : TileDType} {sh : TileShape}
    (e : Op d sh) : Prop :=
  evalOp M p (A.flattenOp e) (flattenState A background flatUndef s) = evalOp M p e s

def ComputeSame {d : ComputeDType} {sh : TileShape} (e : ComputeOp d sh) : Prop :=
  evalComputeOp M (flattenComputeOp A e) (flattenState A background flatUndef s) =
    evalComputeOp M e s

def ComputeCommutes {d : ComputeDType} {sh : TileShape} (e : ComputeOp d sh) : Prop :=
  evalComputeOp M (flattenComputeOp A e) (flattenState A background flatUndef s) =
    (evalComputeOp M e s).map (trValues A)

def ExprCommutes {d : AlgDType} {sh : TileShape} (e : ComputeExpr d sh) : Prop :=
  evalExpr M (flattenExpr A e) (flattenState A background flatUndef s) =
    (evalExpr M e s).map (trValues A)

def FlatWritten (written : RegionName → Nat → Prop) (r : RegionName) (o : Nat) : Prop :=
  r = A.flat ∧ ∃ rr oo, rr ∈ A.regions ∧ oo < A.extent rr ∧
    written rr oo ∧ o = A.addr rr oo

def GridReady {α : Type} (s : State α) : Prop :=
  s.regs .nat [] "pid" = some (fun _ => 0) ∧
  s.regs .nat [] "num_ctas" = some (fun _ => 1)

def footprint (O : RegionName) (base N : Nat) (address : RegionName × Nat) : Prop :=
  address.1 = O ∧ ∃ k, k < N ∧ address.2 = base + k

/-- After c chunks, all active visited lanes satisfy the initial-target gradient formula. -/

def elementFootprint (O : RegionName) (base N : Nat) (address : RegionName × Nat) : Prop :=
  address.1 = O ∧ ∃ k, k < N ∧ address.2 = base + k

/-- Elementwise execution preserves both source regions and verifies every visited active lane. -/

def BackwardSourceSupported (target : Storage) (_output : Storage)
    (logTarget : Bool) : Prop :=
  if logTarget then ExpInputSupported target else NonzeroScalarSupported target

def footprint (O : RegionName) (base N : Nat) (address : RegionName × Nat) : Prop :=
  address.1 = O ∧ ∃ k, k < N ∧ address.2 = base + k

/-- After c chunks, all active visited lanes satisfy the initial-target gradient formula. -/

def Post (A : FlatAlloc) (f : Flags) (r : Regions) (stride : Strides)
    (M N : Nat) (eps p : ℝ) (initial final : BlockState) : Prop :=
  ∀ region offset, final.mem region offset = expected A f r stride M N eps p initial region offset

def Outside (A : FlatAlloc) (f : Flags) (r : Regions) (stride : Strides)
    (M N : Nat) (initial : BlockState) (region : RegionName) (offset : Nat) : Prop :=
  region ≠ A.flat ∨ ∀ q z, Contract.written f r stride M N initial.pid q z → offset ≠ A.addr q z

def ReadWriteSeparated (f : Flags) (r : Regions) : Prop :=
  ∀ input, readRegion f r input → ∀ output, writeRegion f r output → input ≠ output

/-- Exact tagged-cell agreement on every active input region. -/

def ReadsUnchanged (f : Flags) (r : Regions) (current initial : BlockState) : Prop :=
  ∀ region, readRegion f r region → ∀ offset,
    current.mem region offset = initial.mem region offset

def NormalizedReady (rms : Bool) (s : State (WithBot ℝ)) : Prop :=
  Ready s ∧ (∃ std, s.regs .real [] "rstd" = some std) ∧
    (rms = Bool.false → ∃ mean, s.regs .real [] "mean" = some mean)

def activeGrad (s : BlockState) (n BLOCK : Nat)
    (idx : TileIndex [BLOCK, WIDTH]) : Prop :=
  gradRowIndex s BLOCK idx.1 < n

def Agrees (p : Parameters) (pid i : Nat) (c : Coordinates) : Prop :=
  Exact c.row (Schedule.row (rows p) (columns p) p.GM (Schedule.tileId p.SMS pid (i/count p))) ∧
  Exact c.column (Schedule.column (rows p) (columns p) p.GM (Schedule.tileId p.SMS pid (i/count p)))

def outputMask (p : Parameters) (pid q : Nat) (j : TileIndex [p.BM,p.BN]) : Prop :=
  q < RealLoopState.work p pid ∧
    RealStore.active p (RealLoop.tileRow p pid q) (RealLoop.tileColumn p pid q) j

def active (s : BlockState) (H : Nat) (Seqlens : RegionName) (BLOCK_M : Nat)
    (idx : TileIndex [BLOCK_M, BLOCK_DMODEL]) : Prop :=
  mIndex s BLOCK_M idx.1 < seqLen s H Seqlens

def footprint (sm sn : Int) (address : Nat) : Prop :=
  ∃ t < 24, ∃ row < 2, ∃ col < 2,
    address = (offset sm sn (2 * t) row col).toNat

def pbDkActive (i_c i_k T K BTL BK : Nat) (idx : TileIndex [BTL, BK]) : Prop :=
  i_c * BTL + idx.1.val < T ∧ i_k * BK + idx.2.1.val < K

/-- The `dv` store address at lane `(l, p)`. -/

def prbDkActive (i_c i_k T K BTL BK : Nat) (idx : TileIndex [BTL, BK]) : Prop :=
  i_c * BTL + idx.1.val < T ∧ i_k * BK + idx.2.1.val < K

/-- The `dv` store address at lane `(r, p)`. -/

def singleBlockActive (s : BlockState) (T S BS : Nat)
    (idx : TileIndex [BT, BS]) : Prop :=
  idx.1.val < T ∧ sIndex s BS idx.2.1 < S

def Outside (A : FlatAlloc) (p : Layout) (l : Launch) (o region : RegionName)
    (offset : Nat) : Prop :=
  region ≠ A.flat ∨ ∀ q z, footprint p l o (q,z) → offset ≠ A.addr q z

def NoCollision (p : Layout) (l : Launch) : Prop :=
  ∀ (t u : Nat) (i j : Fin p.BS), RealStep.active p l t i.val → RealStep.active p l u j.val →
    address p l t i.val = address p l u j.val → t = u ∧ i = j

def Ready (u : State (WithBot ℝ)) : Prop :=
  (∃ v, u.regs .nat [] "i_bh" = some v) ∧
  (∃ v, u.regs .real [] "b_z" = some v)

def activeQFull (n_qh hd : Nat)
    (idx : TileIndex [pad_n_qh, pad_hd_half]) : Prop :=
  idx.1.val < n_qh ∧ idx.2.1.val < hd / 2

def activeKFull (n_kh hd : Nat)
    (idx : TileIndex [pad_n_kh, pad_hd_half]) : Prop :=
  idx.1.val < n_kh ∧ idx.2.1.val < hd / 2

def active (s : BlockState) (head_dim n_heads ROPE_GROUP_SIZE BLOCK_SIZE : Nat)
    (i : Fin BLOCK_SIZE) : Prop :=
  colIndex i < head_dim / 2 ∧ headStart s ROPE_GROUP_SIZE < n_heads

def activeQFull (n_qh hd : Nat)
    (idx : TileIndex [pad_n_qh, pad_hd_half]) : Prop :=
  idx.1.val < n_qh ∧ idx.2.1.val < hd / 2

def activeKFull (n_kh hd : Nat)
    (idx : TileIndex [pad_n_kh, pad_hd_half]) : Prop :=
  idx.1.val < n_kh ∧ idx.2.1.val < hd / 2

def ropeActive (s : BlockState) (seqlen rotary_dim_half BLOCK_M : Nat)
    (i : Fin BLOCK_HALF) : Prop :=
  ropeRowIndex s BLOCK_M < seqlen ∧ ropeDimIndex i < rotary_dim_half

def Parameters.Geometry (p : Parameters) (s : BlockState) : Prop :=
  Scatter.PairDisjoint (p.qAddress s) (p.activeQ s) ∧
  Scatter.PairDisjoint (p.kAddress s) (p.activeK s)

def PairDisjoint {shape : TileShape} (offset : Bool → TileIndex shape → Nat)
    (active : TileIndex shape → Prop) : Prop :=
  ∀ a b i j, active i → active j → offset a i=offset b j → a=b ∧ i=j

def active (s : BlockState) (q_total_tokens Q_HEAD_NUM BLOCK_TOKENS : Nat) :
    Prop :=
  headIndex s < Q_HEAD_NUM ∧ tokenIndex s BLOCK_TOKENS < q_total_tokens

def activeK (s : BlockState) (q_total_tokens K_HEAD_NUM BLOCK_TOKENS : Nat) :
    Prop :=
  headIndex s < K_HEAD_NUM ∧ tokenIndex s BLOCK_TOKENS < q_total_tokens

def active (s : BlockState) (seqlen rotary_dim_half BLOCK_M : Nat)
    (i : Fin BLOCK_HALF) : Prop :=
  rowIndex s BLOCK_M < seqlen ∧ dimIndex i < rotary_dim_half

def metaActive (IS_VARLEN : Bool) (s : BlockState) (CU : RegionName)
    (seqlen rotary_dim_half BLOCK_M : Nat) (i : Fin BLOCK_HALF) : Prop :=
  metaRm s BLOCK_M < metaSeqlen IS_VARLEN s CU seqlen ∧ i.val < rotary_dim_half

def active (s : BlockState) (seqlen rotary_dim_half BLOCK_M : Nat)
    (i : Fin BLOCK_HALF) : Prop :=
  rowIndex s BLOCK_M < seqlen ∧ dimIndex i < rotary_dim_half

def active2D (s : BlockState) (seqlen rotary_dim_half BLOCK_M : Nat)
    (idx : TileIndex [BLOCK_M, BLOCK_HALF]) : Prop :=
  rowIndex2D s BLOCK_M idx < seqlen ∧ dimIndex2D idx < rotary_dim_half

def metaActive (IS_VARLEN : Bool) (s : BlockState) (CU : RegionName)
    (seqlen rotary_dim_half BLOCK_M : Nat) (i : Fin BLOCK_HALF) : Prop :=
  metaRm s BLOCK_M < metaSeqlen IS_VARLEN s CU seqlen ∧ i.val < rotary_dim_half

def activeLane (s : BlockState) (seq_lens : Region .nat) (N BLOCK_M BLOCK_N : Nat)
    (idx : TileIndex [BLOCK_M, BLOCK_N]) : Prop :=
  rowG s BLOCK_M idx.1 < seqLen s seq_lens ∧ colG s BLOCK_N idx.2.1 < N

def innerBwdActive (s : BlockState) (M N TILE_M : Nat)
    (idx : TileIndex [TILE_M, TILE_N]) : Prop :=
  innerBwdRowIndex s TILE_M idx < M ∧ innerBwdColIndex idx < N

def RegionResult (Y X : RegionName) (N : Nat) (s t : BlockState) : Prop :=
  (∀ j : Fin N, t.readMem Y (linearOffset s N j) = softmaxOptimizeFullSpec s X N j) ∧
    RowFrame Y N s t

def Control (N B p : Nat) (s : BlockState) : Prop :=
  s.regs .nat [] "pid_m" = some (Tile.scalar p) ∧
    s.regs .int [] "prev_multiple" = some (Tile.scalar (prevMultipleNat N B : Int))

def ExprRelated (B : Nat) {dtype : TileDType} {shape : TileShape}
    (a b : Op dtype shape) : Prop :=
  ∀ s t, IndexedRelated B s t → evalOp a s = evalOp b t

def StatementsRelated (B : Nat) (left right : List Stmt) : Prop :=
  ∀ s t, IndexedRelated B s t → ResultsRelated (IndexedRelated B)
    (stepStmts left s) (stepStmts right t)

def active (s : BlockState) (hzRowOffset D0 BLOCK_M : Nat)
    (idx : TileIndex [BLOCK_M, BLOCK_DMODEL]) : Prop :=
  rowIndex s BLOCK_M idx.1 + hzRowOffset < D0

def bwdGradActive (s : BlockState) (D0 BLOCK_M : Nat)
    (idx : TileIndex [BLOCK_M, BLOCK_DMODEL]) : Prop :=
  bwdRowIndex s BLOCK_M idx.1 < D0

def active (s0 : BlockState) (BHW OF batch_dim OH OW OGD : Nat) (idx : TileIndex [BHW, OF]) : Prop :=
  ((batchIdx s0 OH OW BHW idx.1 < batch_dim ∧ featIdx s0 OF idx.2.1 < OGD) ∧
    heightIdx s0 OH OW BHW idx.1 < OH) ∧ widthIdx s0 OW BHW idx.1 < OW

private def pActive (pid₀ pid₁ BHW OF batch_dim OH OW OGD i j : Nat) : Prop :=
  ((pBatch pid₀ OH OW BHW i < batch_dim ∧ pFeat pid₁ OF j < OGD) ∧
    pHeight pid₀ OH OW BHW i < OH) ∧ pWidth pid₀ OW BHW i < OW

def footprint (dst : RegionName) (start : Nat) (length : Int) (B : Nat)
    (addr : RegionName × Nat) : Prop :=
  addr.1 = dst ∧ ∃ n, n < Math.copiedLength length B ∧ addr.2 = start + n

def active (s : BlockState) (old_a_len : RegionName) (_chunk BLOCK_SIZE : Nat)
    (i : Fin BLOCK_SIZE) : Prop :=
  i.val < segmentLength s old_a_len

def touched (length : Int) (B n : Nat) : Prop :=
  ∃ c lane, c * B < length.toNat ∧ lane < B ∧ (lane : Int) < length ∧ n = c * B + lane

/-- Contiguous number of copied elements, including the source's final overcopy. -/

def footprint (dst : RegionName) (start : Nat) (length : Int) (B : Nat)
    (addr : RegionName × Nat) : Prop :=
  addr.1 = dst ∧ ∃ n, n < Math.copiedLength length B ∧ addr.2 = start + n
